import { getVehicleWithData, getPendingMaintenance } from "./actions"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { FAB } from "@/components/fab"
import { Bike, DollarSign, Gauge, Wrench, Clock, Search } from "lucide-react"
import Link from "next/link"

export default async function Home() {
  const vehicleId = "temp-vehicle-id"
  const vehicle = await getVehicleWithData(vehicleId)
  const pending = await getPendingMaintenance(vehicleId)

  const totalSpent = vehicle?.maintenanceLogs.reduce(
    (acc: number, log: { cost: number | null; expenses: { itemCost: number }[] }) => 
      acc + (log.cost || 0) + log.expenses.reduce((e: number, exp: { itemCost: number }) => e + exp.itemCost, 0),
    0
  ) || 0

  return (
    <div className="min-h-screen bg-background pb-24">
      <header className="sticky top-0 z-10 border-b bg-card px-4 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Bike className="h-6 w-6 text-primary" />
            <h1 className="text-lg font-bold">Garage-First</h1>
          </div>
          <Link href="/search">
            <Button variant="ghost" size="icon" className="h-10 w-10">
              <Search className="h-5 w-5" />
            </Button>
          </Link>
        </div>
        <p className="text-sm text-muted-foreground mt-1">
          Kawasaki Ninja 400 • 2020
        </p>
      </header>

      <main className="p-4 space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <Card className="bg-gradient-to-br from-card to-muted">
            <CardContent className="p-4">
              <div className="flex items-center gap-2 text-muted-foreground mb-2">
                <Gauge className="h-4 w-4" />
                <span className="text-xs font-medium">KM Atual</span>
              </div>
              <p className="text-2xl font-bold">{vehicle?.currentKm.toLocaleString() || "0"}</p>
            </CardContent>
          </Card>

          <Card className="bg-gradient-to-br from-card to-muted">
            <CardContent className="p-4">
              <div className="flex items-center gap-2 text-muted-foreground mb-2">
                <DollarSign className="h-4 w-4" />
                <span className="text-xs font-medium">Total Gasto</span>
              </div>
              <p className="text-2xl font-bold">
                R$ {totalSpent.toLocaleString("pt-BR", { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
              </p>
            </CardContent>
          </Card>
        </div>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Clock className="h-4 w-4" />
              Próximas Tarefas / Peças Pendentes
              <Badge variant="secondary" className="ml-auto">
                {pending.length}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {pending.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-4">
                Nenhuma tarefa pendente
              </p>
            ) : (
              pending.slice(0, 5).map((item: { id: string; type: string; description: string; kmAtService: number }) => (
                <div
                  key={item.id}
                  className="flex items-center justify-between p-3 rounded-lg bg-muted/50"
                >
                  <div className="flex items-start gap-3">
                    <div className="mt-0.5">
                      {item.type === "PREVENTIVE" && (
                        <Badge variant="outline" className="text-xs">Preventiva</Badge>
                      )}
                      {item.type === "CORRECTIVE" && (
                        <Badge variant="destructive" className="text-xs">Corretiva</Badge>
                      )}
                      {item.type === "UPGRADE" && (
                        <Badge className="text-xs bg-blue-500">Upgrade</Badge>
                      )}
                    </div>
                    <div>
                      <p className="text-sm font-medium">{item.description}</p>
                      <p className="text-xs text-muted-foreground">
                        KM {item.kmAtService.toLocaleString()}
                      </p>
                    </div>
                  </div>
                </div>
              ))
            )}
            {pending.length > 5 && (
              <Button variant="ghost" className="w-full text-sm">
                Ver mais {pending.length - 5} tarefas
              </Button>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Wrench className="h-4 w-4" />
              Histórico Recente
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {vehicle?.maintenanceLogs.slice(0, 3).map((log: { id: string; description: string; createdAt: Date; status: string }) => (
              <div
                key={log.id}
                className="flex items-center justify-between p-3 rounded-lg bg-muted/50"
              >
                <div>
                  <p className="text-sm font-medium">{log.description}</p>
                  <p className="text-xs text-muted-foreground">
                    {new Date(log.createdAt).toLocaleDateString("pt-BR")}
                  </p>
                </div>
                <Badge variant={log.status === "COMPLETED" ? "default" : "secondary"}>
                  {log.status === "COMPLETED" ? "Concluído" : "Pendente"}
                </Badge>
              </div>
            ))}
            {(vehicle?.maintenanceLogs.length || 0) === 0 && (
              <p className="text-sm text-muted-foreground text-center py-4">
                Nenhum registro ainda
              </p>
            )}
          </CardContent>
        </Card>
      </main>

      <FAB vehicleId={vehicleId} currentKm={vehicle?.currentKm || 0} />
    </div>
  )
}
